static void draw_sprite(unsigned int *vram, const unsigned int *spr, int x, int y) {
    for (int j = 0; j < 24; j++) {
        int py = y + j; if ((unsigned)py >= 272) continue;
        for (int i = 0; i < 24; i++) {
            int px = x + i; if ((unsigned)px >= 480) continue;
            unsigned int c = spr[j * 24 + i]; if (c) vram[py * 512 + px] = c;
        }
    }
}
